import type { PublicQuestion } from "./types";

// PROMPTS ONLY — no answers. Safe to ship to the browser. Generated from
// lib/questions.server.ts by scripts/gen-public-questions.ts — do not edit by hand.
export const PUBLIC_QUESTIONS: PublicQuestion[] = [
  { id: "bbq-1", type: "text", category: "bbq", body: "At long last, it's finally time to get cooking. You've gotten to know your smoker and you've sourced or seasoned the best wood you can possibly find." },
  { id: "bbq-2", type: "text", category: "bbq", body: "Life is too short for bad BBQ!" },
  { id: "bbq-3", type: "text", category: "bbq", body: "I tell people I'm living the dream, because I've turned my hobby into a job." },
  { id: "bbq-4", type: "text", category: "bbq", body: "Didn't have great equipment or great knowledge, but the passion was there. That's never changed." },
  { id: "bbq-5", type: "text", category: "bbq", body: "it's all about cooking delicious food and taking pride in everything we cook" },
  { id: "bbq-6", type: "text", category: "bbq", body: "But the fact that in Texas barbecue, you're taking one of the worst pieces of the animal and converting it into one of the best is a miracle itself." },
  { id: "bbq-7", type: "text", category: "bbq", body: "Sure, I was poor. But barbecue has never been a rich man's pleasure. It's always been a culture of thrift." },
  { id: "bbq-8", type: "text", category: "bbq", body: "I think it's key that you buy the best thing that you can afford." },
  { id: "bbq-9", type: "text", category: "bbq", body: "You learn from your mistakes and you just keep going and trying to do the best you can." },
  { id: "bbq-10", type: "text", category: "bbq", body: "A little beef tallow on the cutting board makes for those sexy slices." },
  { id: "bbq-11", type: "text", category: "bbq", body: "I am an absolute insatiable learner. I love to learn more than anything in the world." },
  { id: "bbq-12", type: "text", category: "bbq", body: "There is a saying in my industry, you buy the meat, not the sauce." },
  { id: "bbq-13", type: "text", category: "bbq", body: "I've always looked at myself as a student of BBQ, because no matter how long you've been doing it, there's always something else to learn." },
  { id: "bbq-14", type: "text", category: "bbq", body: "You can't make a fake fire." },
  { id: "bbq-15", type: "text", category: "bbq", body: "If the temperatures are up and down, it's pretty likely that your firewood is too big, so it's robbing energy from the fire to get to a combustion point." },
  { id: "bbq-16", type: "text", category: "bbq", body: "The worst thing you can do is overcook it." },
  { id: "bbq-17", type: "text", category: "bbq", body: "Like Traeger, I subscribe to the all-natural BBQ philosophy. The hardwood taste and authentic flavors from Traeger's wood fire and wood pellets just can't be beat." },
  { id: "bbq-18", type: "text", category: "bbq", body: "Barbecue feeds your soul because it brings people together." },
  { id: "bbq-19", type: "text", category: "bbq", body: "I do not say I'm lucky. I work too hard to be lucky." },
  { id: "bbq-20", type: "text", category: "bbq", body: "I'd be setting alarms and waking up every 30 minutes; go put a couple logs on the fire, and eventually, it became a business." },
  { id: "bbq-21", type: "text", category: "bbq", body: "There's no shortcut to a perfect brisket, and honestly, there's no shortcut to anything worth having. Low and slow, let it ride, trust the smoke. Fourteen hours on the Traeger and not a single regret. Because the truth is, the best things in life — like the best bark — only come to those who refuse to rush the process." },
  { id: "bbq-22", type: "text", category: "bbq", body: "Let me be clear: a great smoke ring isn't luck, it's commitment. Pellets dialed to 225, a clean fire, and the patience to leave that lid closed. If you're peeking, you're not cooking. Set it, trust it, and let the magic happen. Your taste buds will thank you, and so will your weekend." },
  { id: "bbq-23", type: "text", category: "bbq", body: "Smoked these ribs for six hours and the bark came out absolutely perfect — deeply caramelized, beautifully tender, and bursting with flavor. The Traeger does the heavy lifting so you can focus on what really matters: the people gathered around your table. Good food, good company, good memories. That's the whole point, isn't it?" },
  { id: "bbq-24", type: "text", category: "bbq", body: "Pro tip: temperature is everything. Whether you're running a pork shoulder at 225 or searing a steak at 450, consistency is the secret ingredient no one talks about. Master your heat and you master your craft. And isn't that true of most things worth doing well?" },
  { id: "bbq-25", type: "text", category: "bbq", body: "Day three of the 30-day smoke challenge and today it's pulled pork. Rubbed it down, let it ride at 225, and pulled it at 203 internal. Juicy, smoky, unforgettable. Remember, friends: great barbecue isn't about perfection, it's about showing up and putting in the work, one cook at a time." },
  { id: "bbq-26", type: "text", category: "bbq", body: "Nothing beats the smell of hickory in the morning. That first crack of the lid, that ribbon of blue smoke, that quiet moment before the neighborhood wakes up. Cooking on the Traeger taught me to slow down and savor the in-between. Sometimes the journey really is the destination, my friends." },
  { id: "bbq-27", type: "text", category: "bbq", body: "Brisket 101: trim it, rub it, smoke it, rest it. Don't overthink it. The Traeger handles the precision so you can handle the fun. At the end of the day, barbecue is just love made visible — a way of saying 'I made this for you' without ever saying a word." },
  { id: "bbq-28", type: "text", category: "bbq", body: "Real talk — your smoke ring is a flex, but your patience is the real trophy. Anybody can crank the heat. It takes discipline to let low and slow do its thing. Trust the process, respect the meat, and let time be your co-pilot. Greatness, like good bark, can't be rushed." },
  { id: "bbq-29", type: "text", category: "bbq", body: "Smoked wings, three ways, one Traeger. Crispy skin, tender meat, and a glaze that'll make you question every wing you've ever eaten. Whether you're feeding a crowd or just treating yourself, these deliver every single time. Go ahead — your next game day just found its MVP." },
  { id: "bbq-30", type: "text", category: "bbq", body: "Here's what fifteen years of cooking taught me: the fire doesn't lie. You can fake a lot of things, but you can't fake a properly rendered point. So tend your coals, watch your temps, and stay humble. The pit has a way of teaching patience to those willing to learn." },
  { id: "bbq-31", type: "text", category: "bbq", body: "Sunday reset: a cold drink, a warm fire, and a pork butt that's going nowhere fast. There's a kind of therapy in tending a smoker — no notifications, no rush, just you and the rhythm of the cook. Slow down. Breathe. Let the smoke do the talking." },
  { id: "bbq-32", type: "text", category: "bbq", body: "The secret to fall-off-the-bone ribs? It's not the rub, it's not the sauce — it's respect for the process. Low temps, steady smoke, and the wisdom to know when to walk away. Barbecue rewards the patient and humbles the proud. Cook accordingly, pitmasters." },
  { id: "bbq-33", type: "text", category: "bbq", body: "Pulled this beauty at 204 and let it rest a full hour — and let me tell you, that rest is where the magic happens. So many folks rush this part. Don't. In barbecue, as in life, the waiting is where everything comes together. Trust me on this one." },
  { id: "bbq-34", type: "text", category: "bbq", body: "Cold smoke, warm heart. Today we're doing salmon on the Traeger — delicate, flaky, and kissed with just enough alder to keep it interesting. Cooking for the people you love is the original language, older than words. Fire it up and tell someone you care." },
  { id: "bbq-35", type: "text", category: "bbq", body: "Let's settle the debate: bark beats sauce, every time. A good crust is earned through hours of low heat and patience you can't buy. Sauce is a guest; bark is the host. Build your foundation right and everything else falls into place — on the grill and off it." },
  { id: "bbq-36", type: "text", category: "bbq", body: "Three things every pitmaster needs: a reliable thermometer, a sharp knife, and the patience of a saint. Get those right and the Traeger does the rest. Barbecue isn't a sprint, it's a slow dance with smoke and time. Lean in, stay present, and savor it." },
  { id: "bbq-37", type: "text", category: "bbq", body: "Burnt ends are proof that the best things come from the parts other people throw away. Cube the point, sauce it, smoke it down to candy. There's a little lesson in there about second chances, if you're looking for one. Either way, they disappear off the platter in minutes." },
  { id: "bbq-38", type: "text", category: "bbq", body: "Weeknight win: smoked chicken thighs in under an hour on the Traeger. Juicy, flavorful, and endlessly versatile — toss them on a salad, in a taco, or straight off the rack. Cooking well doesn't have to be complicated; it just has to be done with intention." },
  { id: "bbq-39", type: "text", category: "bbq", body: "Some nights the smoke ring comes out picture-perfect, and some nights it doesn't — and that's okay. Barbecue, like life, isn't about flawless. It's about showing up, learning the fire, and getting a little better with every cook. Progress over perfection, always." },
  { id: "bbq-40", type: "text", category: "bbq", body: "Real pitmasters know: you don't cook the clock, you cook the meat. Probe tender is the only timestamp that matters. Let go of the rush, honor the process, and let that brisket tell you when it's ready. The pit teaches patience to anyone willing to listen." },
  { id: "business-1", type: "text", category: "business", body: "Discipline equals freedom." },
  { id: "business-2", type: "text", category: "business", body: "It's not what you preach, it's what you tolerate." },
  { id: "business-3", type: "text", category: "business", body: "There are no bad teams, only bad leaders." },
  { id: "business-4", type: "text", category: "business", body: "When setting expectations, no matter what has been said or written, if substandard performance is accepted and no one is held accountable—if there are no consequences—that poor performance becomes the new standard." },
  { id: "business-5", type: "text", category: "business", body: "Good is the enemy of great. And that is one of the key reasons why we have so little that becomes great." },
  { id: "business-6", type: "text", category: "business", body: "Greatness is not a function of circumstance. Greatness, it turns out, is largely a matter of conscious choice, and discipline." },
  { id: "business-7", type: "text", category: "business", body: "Great vision without great people is irrelevant." },
  { id: "business-8", type: "text", category: "business", body: "You can make more friends in two months by becoming interested in other people than you can in two years by trying to get other people interested in you." },
  { id: "business-9", type: "text", category: "business", body: "Most people do not listen with the intent to understand; they listen with the intent to reply." },
  { id: "business-10", type: "text", category: "business", body: "People don't buy what you do; they buy why you do it." },
  { id: "business-11", type: "text", category: "business", body: "When it comes to standards, as a leader, it's not what you preach, it's what you tolerate." },
  { id: "business-12", type: "text", category: "business", body: "Good is the enemy of great." },
  { id: "business-13", type: "text", category: "business", body: "Leadership isn't about having all the answers. It's about asking the right questions. The most powerful leaders I've worked with understand that influence flows not from authority, but from curiosity. When you trade certainty for genuine inquiry, you unlock the collective intelligence of the people around you." },
  { id: "business-14", type: "text", category: "business", body: "In today's fast-paced world, the leaders who thrive aren't the ones moving fastest. They're the ones who know when to pause. Speed without direction is just noise. True momentum comes from the quiet discipline of stillness." },
  { id: "business-15", type: "text", category: "business", body: "Culture is not what you say on the walls. It's what you tolerate in the hallways. Every unaddressed behavior is a silent endorsement, and every standard you walk past becomes the new standard you accept." },
  { id: "business-16", type: "text", category: "business", body: "Great teams are not built on talent alone. They are built on trust. Talent fills a roster, but trust fills the gaps that no job description can ever capture. At the end of the day, people don't follow titles. They follow people they believe in." },
  { id: "business-17", type: "text", category: "business", body: "Vision without execution is hallucination. But execution without vision is exhaustion. The art of leadership lives in the delicate balance between dreaming boldly and doing deliberately." },
  { id: "business-18", type: "text", category: "business", body: "The best feedback isn't a verdict. It's a gift. When we reframe criticism as care, we transform a moment of judgment into a moment of growth. People rise to the level of belief we extend to them." },
  { id: "business-19", type: "text", category: "business", body: "Innovation doesn't happen in comfort zones. It happens at the edges, where uncertainty meets courage. The organizations that win tomorrow are the ones brave enough to be uncomfortable today." },
  { id: "business-20", type: "text", category: "business", body: "A leader's most valuable currency is not their expertise. It is their attention. Where you place your focus, you place your priorities. And where you place your priorities, you shape the future of everyone who follows you." },
  { id: "business-21", type: "text", category: "business", body: "Resilience is not the absence of failure. It is the presence of meaning. The strongest organizations don't avoid setbacks. They metabolize them, turning every stumble into a story and every story into a lesson." },
  { id: "business-22", type: "text", category: "business", body: "We often mistake busyness for impact. But motion is not progress, and activity is not achievement. The leaders who matter most are not the ones who do more. They are the ones who do what matters." },
  { id: "business-23", type: "text", category: "business", body: "Empowerment is not a program. It's a posture. You cannot delegate ownership while hoarding control. The moment you trust your people with the why, you free them to discover their own how." },
  { id: "business-24", type: "text", category: "business", body: "The most underrated leadership skill in a disruptive era is listening. Not listening to respond, but listening to understand. In a world drowning in opinions, the rarest act of courage is to truly hear another human being." },
  { id: "disney-1", type: "text", category: "disney", body: "You know, in my defense, your poisons all look alike. You might think about re-labeling some of them." },
  { id: "disney-2", type: "text", category: "disney", body: "Or, to save on postage, I'll just poison him with this." },
  { id: "disney-3", type: "text", category: "disney", body: "Memo to me, memo to me: maim you after my meeting." },
  { id: "disney-4", type: "text", category: "disney", body: "Oh, wonderful! Bravo, bravissimo! You ejected that tin-plated buffoon with great panache!" },
  { id: "disney-5", type: "text", category: "disney", body: "Knock it off, Hugo! She's a girl, not a mackerel." },
  { id: "disney-6", type: "text", category: "disney", body: "Can we be real? If my name was Sebastian and I had a cool Jamaican accent, you'd totally help me. You would, you know you would!" },
  { id: "disney-7", type: "text", category: "disney", body: "Genie, wake up and smell the hummus!" },
  { id: "disney-8", type: "text", category: "disney", body: "Let me illuminate to you the precarious situation in which you have found yourself. I am the one they call when things go wrong, and things have indeed gone wrong." },
  { id: "disney-9", type: "text", category: "disney", body: "Earth is a protected wildlife reserve. Yeah, we've been using it to rebuild the mosquito population which, need I remind you, is an endangered species!" },
  { id: "disney-10", type: "text", category: "disney", body: "Don't listen to that guy. He's trying to lead you down the path of righteousness. I'm gonna lead you down the path that rocks." },
  { id: "disney-11", type: "text", category: "disney", body: "Adventure isn't about being brave! It's about choosing to keep going even when your heart is telling you to stop. And that, my friend, is the truest kind of courage there is." },
  { id: "disney-12", type: "text", category: "disney", body: "Oh, don't you worry your little whiskers about the storm! Storms always pass, and when they do, the sky becomes even more beautiful than before. That's just how the world works." },
  { id: "disney-13", type: "text", category: "disney", body: "I may be just a small, slightly rusty robot, but I have learned that friendship is the one thing that cannot rust, fade, or break down. And I will treasure it forever." },
  { id: "disney-14", type: "text", category: "disney", body: "You think you can stop me? I am chaos! I am the night! I am the thing your parents warned you about when they told you to eat your vegetables!" },
  { id: "disney-15", type: "text", category: "disney", body: "Listen closely, young one, because what I am about to tell you is very important: the magic was never in the amulet at all. The magic was inside you the entire time." },
  { id: "disney-16", type: "text", category: "disney", body: "Cheese? Cheese?! Did somebody say cheese?! Because if there is one thing in this entire wonderful world that I absolutely cannot resist, it is a delicious wedge of cheese!" },
  { id: "disney-17", type: "text", category: "disney", body: "We're lost, we're hungry, and we're being chased by a giant lizard. But you know what? I wouldn't want to be lost, hungry, and chased with anyone else but you." },
  { id: "disney-18", type: "text", category: "disney", body: "Princess, I have traveled across seven kingdoms and battled a thousand foes, but nothing prepared me for the most difficult challenge of all: telling you how I truly feel." },
  { id: "disney-19", type: "text", category: "disney", body: "Failure is simply success that hasn't happened yet! So dust yourself off, hold your head up high, and remember that every great hero started exactly where you are now." },
  { id: "disney-20", type: "text", category: "disney", body: "I used to think being different made me weird. But now I understand that being different is what makes me special, unique, and wonderfully, perfectly me." },
  { id: "speech-1", type: "text", category: "speech", body: "There are these two young fish swimming along and they happen to meet an older fish swimming the other way, who nods at them and says 'Morning, boys. How's the water?' And the two young fish swim on for a bit, and then eventually one of them looks over at the other and goes 'What the hell is water?'" },
  { id: "speech-2", type: "text", category: "speech", body: "The point of the fish story is merely that the most obvious, important realities are often the ones that are hardest to see and talk about." },
  { id: "speech-3", type: "text", category: "speech", body: "With your college diploma you now have a crushing advantage over 8% of the workforce. I'm talking about dropout losers like Bill Gates, Steve Jobs, and Mark Zuckerberg." },
  { id: "speech-4", type: "text", category: "speech", body: "I went from being in the center of the grid to not only off the grid, but underneath the coffee table that the grid sits on, lost in the shag carpeting that is underneath the coffee table supporting the grid." },
  { id: "speech-5", type: "text", category: "speech", body: "If you want to change the world, start off by making your bed." },
  { id: "speech-6", type: "text", category: "speech", body: "If you make your bed every morning you will have accomplished the first task of the day. It will give you a small sense of pride, and it will encourage you to do another task and another and another." },
  { id: "speech-7", type: "text", category: "speech", body: "Death is very likely the single best invention of Life. It is Life's change agent. It clears out the old to make way for the new." },
  { id: "speech-8", type: "text", category: "speech", body: "Stay Hungry. Stay Foolish." },
  { id: "speech-9", type: "text", category: "speech", body: "Graduates, in the realm of human potential, there exists a quiet truth — one that no syllabus could ever fully capture. You stand today at the intersection of who you were and who you are becoming. Life, you will find, is not a destination but a dance between certainty and surprise, between the plans we make and the paths that find us instead. Remember three things as you go forth: be curious, be courageous, and above all, be kind. The world does not need more people who have all the answers. It needs people who are brave enough to ask better questions — and humble enough to keep listening for them." },
  { id: "speech-10", type: "text", category: "speech", body: "When I think about what it means to truly succeed, I keep returning to a single idea — that success is less about what we achieve and more about who we become along the way. In a world that moves faster than ever, it is tempting to measure our worth in titles, in milestones, in the applause of others. But the most meaningful lives are built quietly, in the space between ambition and gratitude. So as you leave this place, I urge you to chase not the spotlight, but the work that makes you feel most alive. Pursue purpose over prestige. Choose growth over comfort. And never, ever forget where you came from." },
  { id: "speech-11", type: "text", category: "speech", body: "There is a beautiful paradox at the heart of this moment. You have spent years learning, and yet the greatest lesson is only beginning — the lesson that you will never stop learning at all. In the realm of the unknown, fear and wonder walk hand in hand, and it is up to you to decide which one leads. I have lived long enough to know that the future belongs not to the certain, but to the curious; not to the loudest, but to the most resilient; not to those who never fall, but to those who rise. Embrace the messiness. Trust the process. The story you are about to write is yours alone." },
  { id: "speech-12", type: "text", category: "speech", body: "Today is not an ending — it is a doorway. And like every doorway worth walking through, it asks something of you: the willingness to step forward without knowing exactly what waits on the other side. The diploma in your hand represents knowledge, yes, but knowledge is only the beginning. Wisdom lives in the dance between what we know and what we have the humility to admit we don't. As you move into the next chapter of your lives, carry three companions with you — patience, persistence, and passion. They will not make the road easy. But they will make the journey worthy of the steps you take." },
  { id: "speech-13", type: "text", category: "speech", body: "Let me share something I have come to believe deeply over the years. The greatest distance any of us will ever travel is not measured in miles — it is the distance between fear and faith, between the comfort of the familiar and the courage to begin again. Each of you carries within you a light that the world has been waiting for. It does not matter whether your path is straight or winding, whether it is celebrated or quiet. What matters is that you walk it with intention, with integrity, and with an open heart. The future is not something that happens to you. It is something you create, one brave decision at a time." },
  { id: "speech-14", type: "text", category: "speech", body: "As you sit here in your caps and gowns, I want you to consider a question that has guided me through every season of my life. Not 'what do you want to do?' but 'who do you want to be?' Because careers will shift, industries will transform, and the world you graduate into today will look nothing like the world you navigate ten years from now. In the realm of constant change, the only true compass is your character. Hold fast to your values. Stay rooted in your purpose. And remember that the measure of a life is not in the heights we reach, but in the hands we lift along the way." },
  { id: "speech-15", type: "text", category: "speech", body: "I will not stand here and pretend I have figured it all out, because the truth is none of us ever do. Life is not a problem to be solved but a mystery to be lived — a delicate dance between holding on and letting go. You will face setbacks that feel like endings and beginnings disguised as detours. Through it all, let three principles steady you: show up fully, fail forward bravely, and lead with empathy. The people who change the world are rarely the smartest in the room. They are simply the ones who refused to give up, who kept believing, who chose hope when hope was hard." },
  { id: "speech-16", type: "text", category: "speech", body: "Look around you for a moment. Look at the faces beside you, the people who laughed with you, struggled with you, and grew alongside you. This is what it was all for — not the grades, not the accolades, but the connections that quietly shaped who you have become. As you go out into a world that often rewards speed over depth and noise over meaning, I ask you to be different. Be the person who pauses. Be the one who listens. Be the light in someone else's darkness. The realm of possibility stretches endlessly before you, and the only limits that matter are the ones you choose to believe in." },
];
